WITH base AS ( SELECT arrayAvg( arrayMap( x -> toFloat64(x.metric), arrayFilter(x -> x.scope='TEMP_SENSOR',column_1) ) )AS temp_avg, arrayAvg( arrayMap( x -> toFloat64(x.metric), arrayFilter(x -> x.scope='HUMID_SENSOR',column_2.nested) ) )AS humidavg FROM database_1.table_1 ) SELECT temp_avg, humidavg FROM base
